cssHead:
body {
  background-color: #F9FAF7;
  color: #203E35;
  font-family: 'Geist', sans-serif;
  -webkit-font-smoothing: antialiased;
}
.sphere-logo {
  width: 32px;
  height: 32px;
  border-radius: 9999px;
  background: radial-gradient(circle at 35% 30%, #a8c7b8 0%, #467362 50%, #203e35 90%);
  box-shadow: 0 4px 10px rgba(32, 62, 53, 0.25), inset 0 1px 2px rgba(255, 255, 255, 0.6);
}
